-- 美食 detail_content 转 HTML 格式
-- ============================================

UPDATE `foods` SET `detail_content` = '<h2>美食简介</h2><p>宁波汤团是宁波最具代表性的传统小吃，已有700多年历史。正宗的宁波汤团采用水磨糯米粉制皮，馅料由绵白糖、黑芝麻和上等猪板油精心调制。</p><h2>风味特色</h2><p>煮熟后的汤团洁白如玉、软糯香甜，咬开后芝麻馅如黑金般流出，香气扑鼻。皮薄馅多，甜而不腻，是宁波人逢年过节必备的美食。</p><h2>推荐餐厅</h2><ul><li><strong>缸鸭狗</strong>：百年老字号，宁波汤团的代表</li><li><strong>状元楼</strong>：传统宁波菜名店</li><li><strong>宁海食府</strong>：本地人推荐的地道口味</li></ul><h2>小贴士</h2><p>汤团趁热食用口感最佳，也可在南塘老街购买速冻汤团作为伴手礼。</p>' WHERE id = 4;

UPDATE `foods` SET `detail_content` = '<h2>美食简介</h2><p>雪菜大黄鱼是宁波十大名菜之一，将新鲜大黄鱼与本地腌制的雪菜同烹，鱼肉鲜嫩，汤汁醇厚。</p><h2>风味特色</h2><p>黄鱼富含蛋白质和不饱和脂肪酸，营养价值极高。雪菜的咸鲜与黄鱼的鲜甜完美融合，汤色乳白，鲜香四溢，是宁波海鲜料理的经典代表。</p><h2>推荐餐厅</h2><ul><li><strong>新石浦大酒店</strong>：海鲜菜品出众</li><li><strong>东福园</strong>：老牌宁波菜馆</li><li><strong>梅龙镇酒家</strong>：口碑上佳的本帮菜</li></ul><h2>小贴士</h2><p>野生大黄鱼价格较高，养殖黄鱼同样鲜美。冬季的黄鱼最为肥美。</p>' WHERE id = 5;

UPDATE `foods` SET `detail_content` = '<h2>美食简介</h2><p>腐皮包黄鱼是宁波传统名菜，将新鲜黄鱼去骨取肉，用薄如蝉翼的豆腐皮包裹后油炸至金黄酥脆。</p><h2>风味特色</h2><p>外层腐皮香脆，内里鱼肉细嫩多汁，蘸上椒盐食用，口感层次丰富。此菜对刀工和火候要求极高，是考验厨师功力的经典之作。</p><h2>推荐餐厅</h2><ul><li><strong>状元楼</strong>：传统做法，风味正宗</li><li><strong>新石浦</strong>：海鲜类菜品口碑出众</li><li><strong>阿拉名灶</strong>：新派宁波菜的代表</li></ul><h2>小贴士</h2><p>此菜需趁热食用，凉后腐皮会变软失去酥脆口感。</p>' WHERE id = 6;

UPDATE `foods` SET `detail_content` = '<h2>美食简介</h2><p>宁波地处东海之滨，盛产梭子蟹。秋季的梭子蟹膏满黄肥，是品蟹的最佳时节。</p><h2>风味特色</h2><p>清蒸梭子蟹能最大程度保留蟹的原汁原味，蟹肉洁白细嫩，蟹膏金黄油润。也可制作成红膏炝蟹，用黄酒和调料腌制，口感更加丰富，是宁波人餐桌上的必备佳肴。</p><h2>经典做法</h2><ul><li><strong>清蒸梭子蟹</strong>：原汁原味，鲜美至极</li><li><strong>红膏炝蟹</strong>：盐渍腌制，蟹膏如火</li><li><strong>葱油梭子蟹</strong>：葱香浓郁，蟹肉入味</li></ul><h2>推荐餐厅</h2><ul><li><strong>老宁波弄堂菜馆</strong>：地道本帮海鲜</li><li><strong>好爸爸</strong>：海鲜大排档人气极高</li><li><strong>原製原味</strong>：食材新鲜，口碑好</li></ul>' WHERE id = 7;

UPDATE `foods` SET `detail_content` = '<h2>美食简介</h2><p>葱烤鲫鱼是宁波传统家常菜，选用新鲜鲫鱼，配以大量京葱，用小火慢煨而成。</p><h2>风味特色</h2><p>烹制过程中，葱的甜香与鱼的鲜美相互渗透，汤汁收干后鱼肉入味，外皮略带焦香。此菜咸鲜适口，是老宁波人记忆中的家乡味道。</p><h2>推荐餐厅</h2><ul><li><strong>老宁波弄堂菜馆</strong>：家常菜做法正宗</li><li><strong>阿毛饭店</strong>：社区人气老店</li><li><strong>甬上名灶</strong>：传统与创新兼具</li></ul><h2>小贴士</h2><p>此菜关键在于小火慢煨，使葱香充分渗入鱼肉。家庭制作时选用新鲜鲫鱼效果更佳。</p>' WHERE id = 8;

UPDATE `foods` SET `detail_content` = '<h2>美食简介</h2><p>红膏炝蟹是宁波独有的传统腌制海鲜，选用深秋时节膏肥体壮的雌梭子蟹，用盐、黄酒等腌制而成。</p><h2>风味特色</h2><p>腌好的炝蟹蟹膏鲜红似火，蟹肉晶莹剔透，入口鲜咸适中，蟹膏绵密醇厚。吃时无需加热，冷食即可，是下酒佐餐的绝佳美味。</p><h2>食用方法</h2><ul><li><strong>冷食</strong>：直接从冰箱取出食用，口感最佳</li><li><strong>配粥</strong>：搭配白粥，鲜咸开胃</li><li><strong>佐酒</strong>：配黄酒，是宁波人最经典的吃法</li></ul><h2>小贴士</h2><p>炝蟹含盐量较高，高血压人群需适量食用。建议在正规餐厅或老字号购买，确保食品安全。</p>' WHERE id = 9;

UPDATE `foods` SET `detail_content` = '<h2>美食简介</h2><p>宁波年糕历史悠久，以慈溪、余姚产的最为著名。传统制法用石磨碾米，蒸熟后反复捶打而成。</p><h2>风味特色</h2><p>年糕质地细腻，久煮不烂，口感软糯有韧劲。"年年高"的美好寓意使其成为春节必备食品。</p><h2>经典吃法</h2><ul><li><strong>炒年糕</strong>：配蔬菜和肉丝翻炒，咸鲜可口</li><li><strong>年糕汤</strong>：清汤煮年糕，简单鲜美</li><li><strong>雪菜年糕</strong>：宁波最经典的组合，咸香入味</li><li><strong>蟹炒年糕</strong>：秋季限定的奢华吃法</li></ul><h2>小贴士</h2><p>水磨年糕保质期较短，真空包装可延长保存时间。可作为伴手礼带回家。</p>' WHERE id = 10;

UPDATE `foods` SET `detail_content` = '<h2>美食简介</h2><p>奉化芋艿头产自奉化区，因得天独厚的水土条件，所产芋艿头个大、皮薄、肉白、质粉。</p><h2>风味特色</h2><p>煮熟后香气扑鼻，入口即化，粉糯香甜。是秋冬时节滋补养生的佳品，民间有"跑过三关六码头，吃过奉化芋艿头"的说法。</p><h2>经典做法</h2><ul><li><strong>白切芋艿</strong>：蘸酱油食用，品尝原味</li><li><strong>芋艿烤肉</strong>：芋香与肉香交融</li><li><strong>芋艿排骨煲</strong>：秋冬暖身佳品</li><li><strong>桂花糖芋艿</strong>：甜品中的经典</li></ul><h2>小贴士</h2><p>奉化芋艿头上市季节为9-11月，此时口感最佳。处理芋艿时建议戴手套避免过敏。</p>' WHERE id = 11;

UPDATE `foods` SET `detail_content` = '<h2>美食简介</h2><p>臭冬瓜是宁波特色腌菜，用传统臭卤发酵而成。虽然气味独特，但味道鲜美，清爽解腻。</p><h2>风味特色</h2><p>与臭豆腐同属"闻着臭、吃着香"的美食，是老宁波人从小吃到大的家乡味。夏季食用尤为清爽开胃，是下饭的绝佳小菜。</p><h2>食用方式</h2><ul><li><strong>蒸食</strong>：保留原味，臭香浓郁</li><li><strong>配粥</strong>：早餐搭配白粥，开胃爽口</li><li><strong>下饭</strong>：夏季佐餐，消暑解腻</li></ul><h2>小贴士</h2><p>初次尝试者建议从少量开始。南塘老街和城隍庙周边可以买到正宗的臭冬瓜。</p>' WHERE id = 12;

UPDATE `foods` SET `detail_content` = '<h2>美食简介</h2><p>龙凤金团是宁波传统糕点，以糯米粉为皮，豆沙、芝麻为馅，用模具压制成型后蒸制。</p><h2>风味特色</h2><p>成品色泽金黄，表面印有龙凤图案，口感软糯香甜。是婚嫁、寿诞等喜庆场合的必备食品，也是日常品茗的佳配。</p><h2>文化寓意</h2><ul><li><strong>龙凤呈祥</strong>：婚嫁场合寓意百年好合</li><li><strong>金团圆满</strong>：团圆节日象征阖家幸福</li><li><strong>祝寿贺喜</strong>：寿诞场合表达美好祝愿</li></ul><h2>小贴士</h2><p>宁波二百、南塘老街等处可购买正宗龙凤金团。趁热食用口感最佳，也可冷食。</p>' WHERE id = 13;

