UPDATE `accommodations` SET `detail_content` = '<h2>酒店简介</h2><p>宁波香格里拉大酒店是城市地标级五星酒店，坐拥三江口绝佳位置，尽揽甬江两岸美景。</p><h2>设施服务</h2><ul><li><strong>客房</strong>：400余间豪华客房，江景房视野极佳</li><li><strong>泳池</strong>：室内恒温泳池，全年可用</li><li><strong>健身中心</strong>：24小时开放，设备齐全</li><li><strong>SPA</strong>：气之专业SPA，放松身心</li></ul><h2>餐饮推荐</h2><ul><li><strong>香宫</strong>：正宗粤菜和宁波本帮菜</li><li><strong>咖啡苑</strong>：自助早餐丰富多样</li></ul><h2>实用信息</h2><p>地处商务核心区，是商务接待和休闲度假的理想选择。距天一广场步行约15分钟。</p>' WHERE id = 4;

UPDATE `accommodations` SET `detail_content` = '<h2>酒店简介</h2><p>宁波威斯汀酒店是威斯汀品牌在浙东地区的旗舰酒店，设计融合现代与东方元素。</p><h2>设施服务</h2><ul><li><strong>客房</strong>：340间客房和套房，配备威斯汀标志性"天梦之床"</li><li><strong>健身房</strong>：24小时开放的WestinWORKOUT健身房</li><li><strong>泳池</strong>：室内恒温泳池</li><li><strong>行政酒廊</strong>：行政楼层专属服务</li></ul><h2>特色体验</h2><p>威斯汀标志性的"天梦之床"让宾客享受极致睡眠体验，SuperFoodsRx营养菜单提供健康美味选择。</p><h2>实用信息</h2><p>位于东部新城核心区，周边商业配套完善，交通便利。</p>' WHERE id = 5;

UPDATE `accommodations` SET `detail_content` = '<h2>酒店简介</h2><p>宁波柏悦酒店坐落于城市天际线制高点，以极简主义设计美学著称。</p><h2>设施服务</h2><ul><li><strong>客房</strong>：200余间宽敞客房和套房，每间配备落地窗可俯瞰城市全景</li><li><strong>餐饮</strong>：精致日料、现代中餐等多种选择</li><li><strong>水疗</strong>：高端水疗中心，提供定制理疗服务</li><li><strong>泳池</strong>：高层无边际泳池，城市美景尽收眼底</li></ul><h2>设计理念</h2><p>酒店内部大量运用天然石材、实木和丝绸等材质，营造出静谧优雅的东方美学空间。</p><h2>实用信息</h2><p>位于南部商务区核心位置，适合追求品质的商旅客人和休闲度假人群。</p>' WHERE id = 6;

UPDATE `accommodations` SET `detail_content` = '<h2>民宿简介</h2><p>云集民宿坐落于慈城古镇核心区，建筑为明清时期古宅，历经修缮后重焕光彩。</p><h2>特色亮点</h2><ul><li><strong>古宅建筑</strong>：保留传统天井院落格局，明清古韵浓厚</li><li><strong>内饰设计</strong>：融合江南水乡风情与现代舒适理念</li><li><strong>文化体验</strong>：可体验茶道、书法等传统文化活动</li></ul><h2>周边游览</h2><p>入住此处，可漫步古镇石板路，品味千年文化底蕴。慈城古镇的孔庙、县衙、校士馆等景点步行可达。</p><h2>实用信息</h2><p>从宁波市区驾车约30分钟。建议提前预订，节假日房源紧张。</p>' WHERE id = 7;

UPDATE `accommodations` SET `detail_content` = '<h2>民宿简介</h2><p>东钱湖畔精品民宿依湖而建，拥有绝佳的湖景视野，是亲近自然的完美选择。</p><h2>特色亮点</h2><ul><li><strong>湖景客房</strong>：共12间客房，每间配有观景阳台</li><li><strong>骑行体验</strong>：清晨可沿湖骑行，感受湖光山色</li><li><strong>品茗观景</strong>：傍晚可在阳台品茗观日落</li><li><strong>特色餐饮</strong>：提供农家餐和户外烧烤服务</li></ul><h2>周边活动</h2><p>东钱湖环湖绿道适合骑行和散步，周边有小普陀、福泉山等景点。</p><h2>实用信息</h2><p>从宁波市区驾车约30分钟。适合周末度假和家庭出游。</p>' WHERE id = 8;

UPDATE `accommodations` SET `detail_content` = '<h2>客栈简介</h2><p>象山渔港客栈紧邻中国六大渔港之一的石浦渔港，由传统渔民建筑改建。</p><h2>特色亮点</h2><ul><li><strong>渔家风情</strong>：装修保留海洋元素，墙上悬挂渔具渔网</li><li><strong>新鲜海鲜</strong>：客栈主人为世代渔民，可代购新鲜海鲜并代为烹饪</li><li><strong>海景房间</strong>：部分房间可观赏渔港日出日落</li></ul><h2>周边游览</h2><p>步行可达石浦古城、中国渔村等景点。每年9月的开渔节期间气氛最为热烈。</p><h2>实用信息</h2><p>从宁波市区驾车约1.5小时。建议安排2天行程，充分体验渔港风情。</p>' WHERE id = 9;

UPDATE `accommodations` SET `detail_content` = '<h2>酒店简介</h2><p>如家酒店天一广场店位于宁波最繁华的商业中心，步行可达天一阁、月湖公园等景点。</p><h2>设施服务</h2><ul><li><strong>标准客房</strong>：配备空调、WiFi、独立卫浴</li><li><strong>交通便利</strong>：周边公交地铁覆盖</li><li><strong>商业配套</strong>：餐饮、购物、娱乐一应俱全</li></ul><h2>适合人群</h2><p>适合预算有限的自由行游客和商务出差人群，性价比高，位置优越。</p><h2>实用信息</h2><p>地铁1号线东门口站步行约5分钟可达。周边餐饮选择丰富。</p>' WHERE id = 10;

UPDATE `accommodations` SET `detail_content` = '<h2>酒店简介</h2><p>汉庭酒店火车站店距宁波站步行仅5分钟，是抵离宁波的最佳住宿选择。</p><h2>设施服务</h2><ul><li><strong>全新装修</strong>：2025年全新装修，汉庭3.5版设计标准</li><li><strong>优质床品</strong>：舒适睡眠体验</li><li><strong>智能设施</strong>：自助入住、智能门锁等</li><li><strong>丰富早餐</strong>：品种多样，营养均衡</li></ul><h2>适合人群</h2><p>适合乘坐高铁抵达宁波的旅客，早班车或晚班车旅客住宿首选。</p><h2>实用信息</h2><p>出宁波站南广场步行5分钟即到。地铁2号线宁波站可直达。</p>' WHERE id = 11;

UPDATE `accommodations` SET `detail_content` = '<h2>旅舍简介</h2><p>宁波国际青年旅舍是YHA国际青年旅舍联盟成员，位于风景秀丽的月湖畔。</p><h2>特色亮点</h2><ul><li><strong>多种房型</strong>：4人间、6人间和双人标间可选</li><li><strong>公共区域</strong>：设有阅读角、公共厨房和露台</li><li><strong>社交氛围</strong>：是结识各地旅友、交流旅行经验的好去处</li><li><strong>优越位置</strong>：月湖畔，步行可达天一阁</li></ul><h2>适合人群</h2><p>适合独行背包客、学生群体和追求社交体验的年轻旅行者。</p><h2>实用信息</h2><p>持YHA会员卡可享优惠价格。公共厨房可自行烹饪，节省餐饮开支。</p>' WHERE id = 12;

UPDATE `accommodations` SET `detail_content` = '<h2>山庄简介</h2><p>雪窦山庄位于国家5A级溪口-滕头旅游景区核心区域，被群山环抱，森林覆盖率高达90%。</p><h2>特色亮点</h2><ul><li><strong>依山而建</strong>：建筑与自然融为一体，环境清幽</li><li><strong>景观阳台</strong>：房间宽敞明亮，可远眺雪窦山美景</li><li><strong>特色美食</strong>：餐厅提供奉化芋头、溪口千层饼等地方美食</li><li><strong>空气清新</strong>：负氧离子浓度极高，天然氧吧</li></ul><h2>周边游览</h2><p>步行可达雪窦寺、千丈岩瀑布等核心景点，是游览溪口景区的最佳下榻之选。</p><h2>实用信息</h2><p>建议提前预订，旺季房源紧张。从宁波市区驾车约1小时。</p>' WHERE id = 13;

