UPDATE `transports` SET `detail_content` = '<h2>基本信息</h2><p>宁波栎社国际机场是浙江省第二大航空港，年旅客吞吐量超过1200万人次。机场现有T1和T2两座航站楼。</p><h2>航线覆盖</h2><ul><li><strong>国内航线</strong>：北京、上海、广州、成都、西安等主要城市</li><li><strong>国际航线</strong>：首尔、东京、新加坡等</li></ul><h2>机场交通</h2><ul><li><strong>地铁</strong>：2号线机场专线直达城区</li><li><strong>机场大巴</strong>：覆盖市区各主要区域</li><li><strong>出租车</strong>：约30分钟可达市中心</li></ul><h2>实用信息</h2><p>建议提前2小时到达机场。T2航站楼为国际出发，T1为国内出发。</p>' WHERE id = 7;

UPDATE `transports` SET `detail_content` = '<h2>基本信息</h2><p>宁波站是宁波市最主要的铁路客运站，2013年全新启用。车站设计现代大气，配备完善的候车和服务设施。</p><h2>高铁线路</h2><ul><li><strong>至杭州</strong>：约1小时</li><li><strong>至上海</strong>：约2小时</li><li><strong>至南京</strong>：约3小时</li><li><strong>至北京</strong>：约5.5小时</li></ul><h2>换乘交通</h2><ul><li><strong>地铁</strong>：2号线宁波站无缝换乘</li><li><strong>公交</strong>：周边公交线路密集</li><li><strong>出租车</strong>：站前广场设有出租车候客区</li></ul><h2>实用信息</h2><p>建议通过12306提前购票。节假日客流量大，请提前到站候车。</p>' WHERE id = 8;

UPDATE `transports` SET `detail_content` = '<h2>基本信息</h2><p>宁波汽车南站位于鄞州区，是浙东地区规模最大的综合客运枢纽。</p><h2>主要线路</h2><ul><li><strong>省际班线</strong>：杭州、上海、南京、温州、台州等</li><li><strong>省内班线</strong>：象山、奉化、宁海等县市</li></ul><h2>换乘交通</h2><ul><li><strong>地铁</strong>：1号线南高教园区站与车站相连</li><li><strong>公交</strong>：多路公交在此设站</li></ul><h2>实用信息</h2><p>建议通过携程、畅途等平台提前查询班次和购票，节假日班次较为紧张。</p>' WHERE id = 9;

UPDATE `transports` SET `detail_content` = '<h2>基本信息</h2><p>宁波轨道交通现已开通1、2、3、4、5号线，总运营里程超过180公里。</p><h2>线路覆盖</h2><ul><li><strong>1号线</strong>：高桥西至霞浦，贯穿东西</li><li><strong>2号线</strong>：栎社机场至聪园路，连接机场</li><li><strong>3号线</strong>：鄞州大道至大通桥，连接南北</li><li><strong>4号线</strong>：慈城至东钱湖，串联景区</li><li><strong>5号线</strong>：布政至荪湖，覆盖北部</li></ul><h2>乘车方式</h2><ul><li><strong>交通卡</strong>：甬城通公交卡</li><li><strong>移动支付</strong>：支付宝、微信均可扫码乘车</li></ul><h2>实用信息</h2><p>运营时间一般为6:00-22:30。高峰时段发车间隔约4-6分钟。</p>' WHERE id = 10;

UPDATE `transports` SET `detail_content` = '<h2>基本信息</h2><p>宁波公共自行车系统是市民和游客短途出行的重要补充。</p><h2>使用方式</h2><ul><li><strong>公共自行车</strong>：凭支付宝芝麻信用免押金借车，1小时内免费</li><li><strong>共享单车</strong>：哈啰、美团等品牌在城区广泛投放</li></ul><h2>推荐骑行线路</h2><ul><li><strong>东钱湖环湖绿道</strong>：湖光山色，风景绝佳</li><li><strong>三江六岸滨江步道</strong>：城市风光，夜景迷人</li><li><strong>月湖公园周边</strong>：文化古迹，移步换景</li></ul><h2>实用信息</h2><p>骑行注意遵守交通规则，佩戴头盔。夏季注意防晒补水。</p>' WHERE id = 11;

UPDATE `transports` SET `detail_content` = '<h2>基本信息</h2><p>宁波旅游观光巴士开通了都市风情线、历史文化线等多条线路，串联主要景点。</p><h2>线路介绍</h2><ul><li><strong>都市风情线</strong>：天一广场→老外滩→三江口→东部新城</li><li><strong>历史文化线</strong>：天一阁→鼓楼→月湖公园→城隍庙</li></ul><h2>乘车体验</h2><p>双层敞篷巴士从天一广场出发，全程约90分钟，配备中英文语音导览。游客可在任意站点上下车，是初次到访宁波的游客了解城市的绝佳方式。</p><h2>实用信息</h2><p>建议购买一日票，可不限次数乘坐。节假日运营时间会延长。</p>' WHERE id = 12;

UPDATE `transports` SET `detail_content` = '<h2>基本信息</h2><p>宁波水上巴士以三江口为中心，开通了多条航线。</p><h2>航线亮点</h2><ul><li><strong>日间航班</strong>：沿江而行，欣赏老外滩、外滩大桥、庆安会馆等景观</li><li><strong>夜间航班</strong>：两岸灯火璀璨，流光溢彩，是感受宁波都市魅力的独特方式</li></ul><h2>沿途景观</h2><ul><li><strong>老外滩</strong>：百年开埠历史街区</li><li><strong>外滩大桥</strong>：城市地标性桥梁</li><li><strong>庆安会馆</strong>：全国重点文保单位</li></ul><h2>实用信息</h2><p>夜间航班尤为推荐，最佳观赏时间19:00-21:00。航班时刻和票价请关注宁波水上巴士官方信息。</p>' WHERE id = 13;

UPDATE `transports` SET `detail_content` = '<h2>基本信息</h2><p>宁波设有多个长途汽车客运站，覆盖省内外主要城市。</p><h2>主要客运站</h2><ul><li><strong>汽车南站</strong>：主营省际和部分省内班线</li><li><strong>汽车北站</strong>：发往杭州湾新区和慈溪方向</li><li><strong>汽车东站</strong>：服务北仑、镇海等区域</li></ul><h2>热门线路</h2><ul><li><strong>宁波→普陀山</strong>：约3小时，途经舟山跨海大桥</li><li><strong>宁波→乌镇/西塘</strong>：约3-4小时</li><li><strong>宁波→台州/温州</strong>：约2-3小时</li></ul><h2>实用信息</h2><p>各客运站均接入公交网络，部分站点地铁可达。建议通过携程、畅途等平台提前查询班次和购票。</p>' WHERE id = 14;

