UPDATE `strategies` SET `detail_content` = '<h2>Day 1 · 市区文化之旅</h2><ul><li><strong>上午 天一阁博物院</strong> — 参观中国最古老的私家藏书楼，约2小时</li><li><strong>午餐</strong> — 品尝状元楼宁波菜</li><li><strong>下午 月湖公园·鼓楼步行街</strong> — 漫步月湖，感受古城韵味</li><li><strong>晚上 老外滩</strong> — 体验三江口夜生活</li></ul><h2>Day 2 · 东钱湖休闲游</h2><ul><li><strong>上午</strong> — 环湖骑行或乘船游湖，参观小普陀、福泉山</li><li><strong>午餐</strong> — 品尝湖畔农家菜</li><li><strong>下午</strong> — 返回市区，逛天一广场</li></ul><h2>Day 3 · 溪口雪窦山</h2><ul><li><strong>上午</strong> — 乘车前往溪口（约1.5小时），参观蒋氏故居</li><li><strong>下午</strong> — 游览雪窦山风景区，千丈岩瀑布</li><li><strong>美食</strong> — 品尝溪口千层饼、芋艿头等特色美食</li></ul><h2>实用建议</h2><p>三日行程较为紧凑，建议根据个人节奏适当调整。自驾出行最为灵活方便。</p>' WHERE id = 6;

UPDATE `strategies` SET `detail_content` = '<h2>必吃美食</h2><ul><li><strong>红膏炝蟹</strong> — 宁波独有的传统腌制海鲜</li><li><strong>雪菜大黄鱼</strong> — 宁波十大名菜之一</li><li><strong>宁波汤团</strong> — 黑芝麻馅的经典小吃</li><li><strong>年糕</strong> — 慈溪水磨年糕，久煮不烂</li><li><strong>臭冬瓜</strong> — 闻着臭吃着香的传统美味</li></ul><h2>推荐餐厅</h2><ul><li><strong>缸鸭狗</strong>：汤团老字号</li><li><strong>状元楼</strong>：正宗宁波菜</li><li><strong>新石浦</strong>：海鲜大排档</li><li><strong>阿毛饭店</strong>：家常菜人气店</li></ul><h2>夜宵圣地</h2><p>南塘老街、城隍庙美食街是宵夜好去处。</p><h2>伴手礼推荐</h2><p>年糕、汤团粉、龙凤金团、奉化芋艿、海鲜干货等。秋季的梭子蟹、冬季的带鱼最为肥美。</p>' WHERE id = 7;

UPDATE `strategies` SET `detail_content` = '<h2>推荐亲子景点</h2><ul><li><strong>罗蒙环球乐园</strong> — 室内主题乐园，不受天气影响</li><li><strong>宁波海洋世界</strong> — 海洋生物科普，孩子最爱</li><li><strong>宁波科学探索中心</strong> — 互动科学体验</li><li><strong>东钱湖水上乐园</strong> — 夏季清凉首选</li><li><strong>象山影视城</strong> — 古装体验，寓教于乐</li></ul><h2>亲子餐饮</h2><p>各大商场内均有适合儿童的餐厅，推荐选择带儿童活动区的餐厅。</p><h2>住宿建议</h2><p>选择带儿童设施的星级酒店或亲子主题民宿，部分酒店提供儿童托管服务。</p><h2>注意事项</h2><ul><li>夏季注意防暑降温，备好防晒用品</li><li>提前预订热门景点门票，避免排队</li><li>准备好儿童身份证明享受优惠</li></ul>' WHERE id = 8;

UPDATE `strategies` SET `detail_content` = '<h2>前童古镇</h2><p>宁海县境内，760年历史，明清建筑保存完好。元宵行会、豆腐节等民俗活动精彩纷呈。前童豆腐和三宝是当地特色美食。</p><h2>慈城古镇</h2><p>宁波市区最近的古镇，江南第一古县城。孔庙、县衙等古建筑值得一看，云集民宿可体验古宅住宿。</p><h2>鸣鹤古镇</h2><p>1200年历史，依山傍水。国医馆旧址见证当年药材商帮的繁华，年糕饺和梅花糕是必尝小吃。</p><h2>游览建议</h2><ul><li>选择工作日前往避开人流</li><li>预留半天到一天时间慢慢探索</li><li>穿舒适的平底鞋，古镇多石板路</li><li>带好相机，古镇处处是风景</li></ul>' WHERE id = 9;

UPDATE `strategies` SET `detail_content` = '<h2>象山松兰山</h2><p>宁波最近的海滨度假区，沙滩细软，适合亲子玩沙戏水。自驾约1.5小时可达。</p><h2>石浦渔港</h2><p>中国六大渔港之一，海鲜美食天堂，可乘船出海体验渔民生活。每年9月开渔节气氛热烈。</p><h2>渔山列岛</h2><p>被誉为"亚洲第一钓场"，海水清澈见底，是潜水和观日出的绝佳去处。需从石浦乘船约1.5小时。</p><h2>实用建议</h2><ul><li><strong>最佳季节</strong>：5-10月，避开台风季节</li><li><strong>交通</strong>：建议自驾，海岛需乘船</li><li><strong>住宿</strong>：松兰山有度假酒店，渔山列岛住宿有限需提前预订</li><li><strong>必备物品</strong>：防晒霜、泳衣、防滑鞋</li></ul>' WHERE id = 10;

UPDATE `strategies` SET `detail_content` = '<h2>樱花 · 3月中至4月初</h2><ul><li><strong>鄞州公园</strong> — 市区最大樱花林</li><li><strong>日湖公园</strong> — 湖畔赏樱胜地</li><li><strong>宁波大学</strong> — 校园樱花大道</li></ul><h2>油菜花 · 3-4月</h2><p>奉化、象山大片油菜花海，金色花浪与蓝天辉映。</p><h2>杜鹃花 · 4-5月</h2><p>四明山区漫山遍野的野生杜鹃，红似火、粉如霞。</p><h2>桃花 · 3月</h2><p>奉化林家村"天下第一桃园"，十里桃花灼灼其华。</p><h2>郁金香 · 3-4月</h2><p>东钱湖郁金香花展，品种繁多色彩斑斓。</p><h2>赏花贴士</h2><ul><li>关注花期预报，花期受天气影响较大</li><li>工作日前往避开周末高峰</li><li>备好相机记录春日美景</li></ul>' WHERE id = 11;

UPDATE `strategies` SET `detail_content` = '<h2>环东钱湖线</h2><p>约50公里，沿湖风光秀丽，串联小普陀、福泉山、陶公岛等景点。适合半日休闲自驾。</p><h2>象山滨海线</h2><p>宁波→松兰山→石浦→花岙岛，全程约150公里。海岛风情尽收眼底，建议安排2天行程。</p><h2>四明山盘山线</h2><p>梁弄→四明山森林公园→大岚镇，山路蜿蜒，秋季红叶尤为壮观。全程约80公里。</p><h2>自驾贴士</h2><ul><li>山区道路弯多坡陡，注意安全驾驶</li><li>海边停车场假日紧张，建议早出发</li><li>四明山冬季可能有冰雪，需备防滑链</li><li>沿途加油站分布较稀，提前加满油</li></ul>' WHERE id = 12;

UPDATE `strategies` SET `detail_content` = '<h2>综合商场</h2><ul><li><strong>天一广场</strong> — 市中心最大商业综合体</li><li><strong>印象城</strong> — 东部新城时尚购物</li><li><strong>万象城</strong> — 江北高端购物中心</li></ul><h2>特色街区</h2><ul><li><strong>南塘老街</strong> — 传统手工艺品和宁波小吃</li><li><strong>城隍庙</strong> — 小商品和本地特色</li><li><strong>1844艺术街区</strong> — 文创产品和设计师店铺</li></ul><h2>推荐伴手礼</h2><ul><li>年糕、汤团粉 — 宁波传统主食</li><li>黄泥螺、海鲜干货 — 海味特产</li><li>龙凤金团 — 传统喜庆糕点</li><li>奉化水蜜桃 — 夏季限定鲜果</li></ul><h2>购物贴士</h2><p>宁波二百是本地老字号百货，特产专柜品种齐全。各大超市也设有特产专区。</p>' WHERE id = 13;
